static const u8 enemy_anim_slot[42] = { 0x14, 0x00, 0x15, 0x16, 0x38, 0x22, 0x3C, 0x25, 0x40, 0x27, 0x44, 0x48, 0x49, 0x4A, 0x40, 0x4C, 0x4D, 0x4E, 0x50, 0x7C, 0x7D, 0x51, 0x45, 0x4F, 0x4F, 0x4F, 0x4F, 0x4F, 0x4F, 0x4F, 0x4F, 0x4F, 0x46, 0x00, 0x00, 0xD8, 0xD9, 0xD4, 0xD0, 0xDA, 0xDB, 0xDC };
static const u8 enemy_anim_bit[8] = { 0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80 };

// Called by the entity renderer on every 16th frame. Each enemy type present
// uploads the frame for this beat once into its canonical slot; bodies whose
// sprite_tile was re-pointed (bosses, special poses) are left alone.
void enemy_anim_tick(void) BANKED {
    u8 i, eid, n, u, m;
    /* 6 bytes cover EID 0..47; N_EIDS is 42 so IDs 40-41 must not wrap. */
    u8 done[6];
    u8 beat = (u8)((entity_anim_counter >> 4) & 1);
    entity_t *e = entities;
    done[0] = done[1] = done[2] = done[3] = done[4] = done[5] = 0;
    for (i = 0; i < MAX_ENTITIES; ++i, ++e) {
        if (!(e->flags & EF_ACTIVE) || e->type != ENT_ENEMY) continue;
        eid = e->ai_data[0];
        if (eid >= sizeof(enemy_anim_unit)) continue;
        u = enemy_anim_unit[eid];
        if (u == 0xFF || e->sprite_tile != enemy_anim_slot[eid]) continue;
        m = enemy_anim_bit[eid & 7];
        if (done[eid >> 3] & m) continue;
        done[eid >> 3] |= m;
        n = enemy_anim_tiles[eid];
        if (beat) u = (u8)(u + n);
        set_sprite_data(e->sprite_tile, n, enemy_anim_atlas + ((u16)u << 4));
    }
}
